import { t, tAll } from './i18n.js';
import { blocked } from './billing-state.js';
// Excel and PDF export. Libraries are loaded on demand from a CDN (only when the user clicks Export).
// Usage:  await exportExcel('sales-2026-11', [{ name: 'Sales', rows: [['Date','Total'], ['2026-11-01', 1000]] }]);
//         await exportPDF('Income statement', { subtitle: 'Nov 2026', columns: ['Item','Amount'], rows: [['Revenue','1,000']], footer: 'Generated by FBBMS' });
const load = (src, test) => new Promise((res, rej) => {
  if (test()) return res();
  const s = document.createElement('script'); s.src = src; s.onload = () => res(); s.onerror = () => rej(new Error('Could not load the export library. Check your internet connection.')); document.head.appendChild(s);
});
const save = (blob, name) => { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 4000); };

export async function exportExcel(filename, sheets) {
  if (blocked('export')) return;
  await load('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js', () => window.XLSX);
  const wb = window.XLSX.utils.book_new();
  sheets.forEach((s, i) => {
    s = { ...s, name: t(String(s.name || '')), rows: s.rows.map(tAll) };
    const ws = window.XLSX.utils.aoa_to_sheet(s.rows);
    const widths = s.rows.reduce((w, r) => { r.forEach((c, j) => { w[j] = Math.min(48, Math.max(w[j] || 8, String(c ?? '').length + 2)); }); return w; }, []);
    ws['!cols'] = widths.map(wch => ({ wch }));
    window.XLSX.utils.book_append_sheet(wb, ws, String(s.name || 'Sheet' + (i + 1)).replace(/[\\/?*[\]:]/g, ' ').slice(0, 31));
  });
  const out = window.XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
  save(new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), filename.replace(/\.xlsx$/, '') + '.xlsx');
}

export async function exportPDF(title, { subtitle = '', columns = [], rows = [], footer = '', landscape = false, sections = null } = {}) {
  if (blocked('export')) return;
  await load('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js', () => window.jspdf);
  await load('https://cdn.jsdelivr.net/npm/jspdf-autotable@3.8.2/dist/jspdf.plugin.autotable.min.js', () => window.jspdf && window.jspdf.jsPDF.API.autoTable);
  const fileTitle = title; title = t(title); subtitle = t(subtitle); footer = t(footer); columns = tAll(columns); rows = rows.map(tAll);
  if (sections) sections = sections.map(p => ({ ...p, heading: p.heading && t(p.heading), columns: tAll(p.columns), rows: p.rows.map(tAll) }));
  const doc = new window.jspdf.jsPDF({ orientation: landscape ? 'landscape' : 'portrait', unit: 'pt', format: 'a4' });
  doc.setFontSize(16); doc.text(String(title), 40, 48);
  if (subtitle) { doc.setFontSize(10); doc.setTextColor(110); doc.text(String(subtitle), 40, 64); doc.setTextColor(0); }
  let y = 80;
  const parts = sections || [{ columns, rows }];
  parts.forEach(p => {
    if (p.heading) { doc.setFontSize(12); doc.text(String(p.heading), 40, y + 10); y += 16; }
    doc.autoTable({ startY: y, head: [p.columns], body: p.rows.map(r => r.map(c => String(c ?? ''))), styles: { fontSize: 9, cellPadding: 4 }, headStyles: { fillColor: [40, 40, 48] }, margin: { left: 40, right: 40 } });
    y = doc.lastAutoTable.finalY + 22;
  });
  if (footer) { doc.setFontSize(8); doc.setTextColor(130); doc.text(String(footer), 40, doc.internal.pageSize.getHeight() - 24); }
  doc.save(fileTitle.replace(/[^\w\-]+/g, '_').slice(0, 60) + '.pdf');
}

/** Adds "Excel" and "PDF" buttons into a container; getData() returns { filename, title, subtitle, columns, rows, sheets? }. */
export function exportButtons(container, getData) {
  container.insertAdjacentHTML('beforeend', '<button class="btn btn-soft" data-x="xlsx"><i class="bi bi-file-earmark-excel me-1"></i>Excel</button><button class="btn btn-soft" data-x="pdf"><i class="bi bi-file-earmark-pdf me-1"></i>PDF</button>');
  container.querySelectorAll('[data-x]').forEach(b => b.onclick = async () => {
    const old = b.innerHTML; b.disabled = true; b.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
    try { const d = await getData(); if (b.dataset.x === 'xlsx') await exportExcel(d.filename, d.sheets || [{ name: d.title, rows: [d.columns, ...d.rows] }]); else await exportPDF(d.title, d); }
    catch (e) { const { fail } = await import('./ui.js'); fail(e); }
    b.disabled = false; b.innerHTML = old;
  });
}
